  "GamificationRealmConfig": {"type": "object", "required": ["ecosystemId", "mode", "skin", "surfaces", "seasons", "timezone"], "properties": {"ecosystemId": {"type": "string"}, "mode": {"type": "string", "enum": ["none", "gamification", "game"], "description": "'none' leaves telemetry flowing but suppresses awards/UI; 'gamification' turns on badges/levels/streaks/leaderboards; 'game' is a dedicated playable game, which brings gamification with it"}, "skin": {"type": "string", "enum": ["rpg", "plain"]}, "surfaces": {"type": "object", "additionalProperties": {"type": "boolean"}, "description": "Per-surface toggles; a surface is ON unless set false"}, "seasons": {"$ref": "#/components/schemas/GamificationSeasons", "description": "Season board window config; null ⇒ seasons off"}, "timezone": {"type": "string", "description": "IANA timezone for the realm's day/streak boundary (Night Owl); defaults to 'UTC'"}}},
