  "MarkdownDocumentSummary": {"type": "object", "required": ["id", "title", "excerpt", "contentHash", "sizeBytes", "currentVersion", "tags", "visibility", "stage", "kind", "createdAt", "updatedAt"], "properties": {"id": {"type": "string"}, "title": {"type": "string", "description": "Server-derived, read-only: the frontmatter `title` then `name`, else the first non-empty line of the body (frontmatter and code fences ignored, leading markdown syntax stripped), else 'Untitled'. Capped at 500 characters."}, "excerpt": {"type": "string", "description": "Server-derived, read-only preview: up to 4 body lines FOLLOWING the title line, newline-separated, each capped at 160 characters and stripped of leading markdown syntax. Empty when the body holds nothing past its title. Exists because this projection carries no `content` — it is what lets a list render a preview without fetching every document whole."}, "frontmatter": {"type": "object", "additionalProperties": true, "nullable": true}, "category": {"type": "string", "nullable": true}, "tags": {"type": "array", "items": {"type": "string"}}, "visibility": {"type": "string", "enum": ["private", "public"]}, "stage": {"type": "string", "enum": ["draft", "final"]}, "kind": {"type": "string", "enum": ["paper", "research"]}, "publicRoute": {"type": "string", "nullable": true}, "contentHash": {"type": "string"}, "sizeBytes": {"type": "integer"}, "currentVersion": {"type": "integer"}, "latestVersionId": {"type": "string", "nullable": true}, "createdAt": {"type": "string"}, "updatedAt": {"type": "string"}}},
