  "Project": {"type": "object", "required": ["id", "name", "description", "status", "color", "estimateScale", "priorityScale", "itemNoun", "itemNounPlural", "keyPrefix", "createdAt", "updatedAt", "isDeleted", "syncVersion", "customerId", "ecosystemId", "ownerKind", "ownerId", "health", "healthUpdatedAt"], "properties": {"id": {"type": "string"}, "name": {"type": "string"}, "description": {"type": "string"}, "status": {"type": "string", "description": "lifecycle status (DB default 'active')"}, "color": {"type": "string", "description": "hex board accent (DB default #007AFF)"}, "estimateScale": {"type": "string", "enum": ["none", "points", "fibonacci", "exponential", "linear", "tshirt"], "description": "how this board writes estimates (DB default 'none' — the board does not estimate). Advisory: it tells a client which picker to render, and constrains nothing the API accepts."}, "priorityScale": {"type": "string", "enum": ["standard", "none"], "description": "whether this board ranks its work (DB default 'standard'). Advisory in the same way: 'none' means render no priority control and no priority column, and the API still accepts and returns the 0–4 integer every card already carries."}, "itemNoun": {"type": "string", "description": "what this board calls ONE of its items, lower-case (DB default 'work item') — the word a client puts in 'New …', in an empty state and in a bulk-action count"}, "itemNounPlural": {"type": "string", "description": "what this board calls MANY of its items (DB default 'work items'). Stored rather than derived from itemNoun: English pluralisation is not a rule this API can pretend to know ('story' → 'storys'), so the word is the author's."}, "createdAt": {"type": "string"}, "updatedAt": {"type": "string"}, "isDeleted": {"type": "boolean"}, "syncVersion": {"type": "integer"}, "customerId": {"type": "string", "description": "the customer (user) who created the project"}, "deletedAt": {"type": "string", "nullable": true}, "ecosystemId": {"type": "string", "description": "the owning ecosystem (tenant scope)"}, "archivedAt": {"type": "string", "nullable": true, "description": "ISO timestamp when archived; null = not archived"}, "ownerKind": {"type": "string", "enum": ["customer", "organization"], "description": "the kind of principal that OWNS the project"}, "ownerId": {"type": "string", "description": "the owning principal (customer or organization id); server-stamped from the verified ?workspace= scope, else the creator"}, "keyPrefix": {"type": "string", "description": "the prefix every card's key is rendered from (ADH-42) — 2–8 chars, a letter then letters or digits, stored upper-cased and unique among the OWNER's live boards. '' = unassigned (a project predating migration 0181, until the backfill reaches it); its cards render an empty key rather than a broken one."}, "startDate": {"type": "string", "nullable": true, "description": "date (YYYY-MM-DD); null = no committed start"}, "targetDate": {"type": "string", "nullable": true, "description": "date (YYYY-MM-DD); never before startDate; null = no committed target"}, "leadKind": {"type": "string", "enum": ["customer", "persona", "team", null], "nullable": true, "description": "the kind of principal that ANSWERS for the project. Whole or absent: a lead is always a kind AND an id, never half of one."}, "leadId": {"type": "string", "nullable": true, "description": "set with leadKind (both or neither)"}, "programId": {"type": "string", "nullable": true, "description": "the program this board rolls up into; null = it stands alone. The program belongs to the project's OWNER, so a workspace can group boards without a project ever naming a container another workspace runs."}, "health": {"type": "string", "enum": ["on_track", "at_risk", "off_track", null], "nullable": true, "description": "DERIVED, never stored: the health on the NEWEST live status update (GET /project/projects/{id}/status-updates returns it first). null means no update has been posted — which is not \"on track\", and the distinction is the reason this is not a column with a default. Retracting the newest update moves it back to the previous one, or to null."}, "healthUpdatedAt": {"type": "string", "nullable": true, "description": "when the update that decided `health` was posted; null exactly when `health` is null. A dashboard needs this to say whether a green board is green or merely stale."}}},
  "ProjectStatus": {"type": "object", "required": ["id", "ecosystemId", "projectId", "key", "label", "category", "position", "createdAt"], "properties": {"id": {"type": "string"}, "ecosystemId": {"type": "string"}, "projectId": {"type": "string"}, "key": {"type": "string", "description": "stable identifier, unique within the project"}, "label": {"type": "string"}, "category": {"type": "string", "enum": ["backlog", "todo", "in_progress", "done", "canceled"]}, "position": {"type": "integer", "description": "column order (ascending)"}, "createdAt": {"type": "string"}}},
