  "PublicUserSearchHit": {"type": "object", "required": ["slug", "displayName", "avatarUrl", "kind"], "properties": {"slug": {"type": "string"}, "displayName": {"type": "string", "nullable": true}, "avatarUrl": {"type": "string", "nullable": true}, "kind": {"type": "string", "enum": ["user", "organization"]}}},
  "PublicUserProfile": {"type": "object", "required": ["slug", "displayName", "avatarUrl", "createdAt", "socialLinks", "emails", "phones", "addresses", "personas"], "properties": {"slug": {"type": "string"}, "displayName": {"type": "string", "nullable": true}, "avatarUrl": {"type": "string", "nullable": true}, "createdAt": {"type": "string"}, "socialLinks": {"type": "array", "items": {"$ref": "#/components/schemas/PublicSocialLink"}}, "emails": {"type": "array", "items": {"type": "string"}}, "phones": {"type": "array", "items": {"type": "string"}}, "addresses": {"type": "array", "items": {"$ref": "#/components/schemas/PublicAddress"}}, "personas": {"type": "array", "items": {"$ref": "#/components/schemas/PublicPersonaSummary"}}}},
  "PublicOrgProfile": {"type": "object", "required": ["slug", "displayName", "description", "createdAt", "personas"], "properties": {"slug": {"type": "string"}, "displayName": {"type": "string"}, "description": {"type": "string", "nullable": true}, "createdAt": {"type": "string"}, "personas": {"type": "array", "items": {"$ref": "#/components/schemas/PublicPersonaSummary"}}}},
