  "AccessAuditEntry": {"type": "object", "required": ["id", "ownerKind", "ownerId", "actorKind", "actorId", "actorEmail", "action", "subjectKind", "subjectId", "targetFeature", "targetItemId", "roleId", "before", "after", "at"], "properties": {"id": {"type": "string"}, "ownerKind": {"type": "string"}, "ownerId": {"type": "string"}, "actorKind": {"type": "string"}, "actorId": {"type": "string"}, "actorEmail": {"type": "string", "nullable": true}, "action": {"type": "string"}, "subjectKind": {"type": "string", "nullable": true}, "subjectId": {"type": "string", "nullable": true}, "targetFeature": {"type": "string", "nullable": true}, "targetItemId": {"type": "string", "nullable": true}, "roleId": {"type": "string", "nullable": true}, "before": {"nullable": true, "description": "Pre-change state (action-shaped)"}, "after": {"nullable": true, "description": "Post-change state (action-shaped)"}, "at": {"type": "string"}}},
  "AccessAuditPage": {"type": "object", "required": ["items", "page", "pageSize", "total"], "properties": {"items": {"type": "array", "items": {"$ref": "#/components/schemas/AccessAuditEntry"}}, "page": {"type": "integer"}, "pageSize": {"type": "integer", "description": "Clamped 1..200"}, "total": {"type": "integer", "description": "Saturates at a 10,000-row count cap"}}},
  "ReservedIdentifier": {"type": "object", "required": ["rdid", "entityType", "entityId", "reason", "heldSince", "releasable"], "properties": {"rdid": {"type": "string"}, "entityType": {"type": "string"}, "entityId": {"type": "string"}, "reason": {"type": "string", "enum": ["rename-leftover", "orphan", "deleted-entity"], "description": "What is holding the name, and therefore what releasing it does: an in-window rename alias and an orphaned mapping are deleted; a deleted entity is RENAMED to a placeholder and its subtree moves with it."}, "heldSince": {"type": "string", "nullable": true, "description": "When the name got stuck: an alias's supersede instant, else the row's last write"}, "releasable": {"type": "boolean", "description": "False for names this surface can only report — a revoked token slug (reserved by policy) and legacy reverse-domain handles. Releasing one answers 403."}}},
  "ReservedIdentifierPage": {"type": "object", "required": ["items", "page", "pageSize", "total", "truncated"], "properties": {"items": {"type": "array", "items": {"$ref": "#/components/schemas/ReservedIdentifier"}}, "page": {"type": "integer"}, "pageSize": {"type": "integer", "description": "Clamped 1..200"}, "total": {"type": "integer", "description": "Saturates at a 2,000-row cap: the list merges heterogeneous sources and cannot be paged by a single SQL OFFSET"}, "truncated": {"type": "boolean", "description": "A held name is missing from this response — a source scan came back at its cap, or the merge overflowed the overall one. Clients that filter client-side MUST surface this: past the cap an empty result is not evidence that a name is free."}}},
  "ReleaseResult": {"type": "object", "required": ["rdid", "reason", "freed", "aliasesRemoved", "stillHeldBy"], "properties": {"rdid": {"type": "string"}, "reason": {"type": "string", "enum": ["rename-leftover", "orphan", "deleted-entity"]}, "freed": {"type": "boolean", "description": "The released NAME is available again. Deliberately not \"the surrounding namespace is empty\" — a different type sharing that path is a different name."}, "placeholder": {"type": "string", "description": "The name the entity was renamed to, when the release was a rename"}, "aliasesRemoved": {"type": "integer"}, "stillHeldBy": {"type": "array", "items": {"type": "string"}, "description": "Canonical addresses still sitting in that space, informational. Read as \"these exist nearby\", never as \"the release failed\"."}}},
  "AdminNote": {"type": "object", "description": "An operator note attached to some other row. Never visible to that row’s subject.", "required": ["id", "ecosystemId", "subjectTable", "subjectId", "content", "createdBy", "createdAt", "updatedAt"], "properties": {"id": {"type": "string", "maxLength": 36}, "ecosystemId": {"type": "string", "maxLength": 36}, "subjectTable": {"type": "string", "maxLength": 120}, "subjectId": {"type": "string", "maxLength": 36}, "content": {"type": "string"}, "createdBy": {"type": "string", "maxLength": 36}, "createdAt": {"type": "string"}, "updatedAt": {"type": "string"}}},
  "AdminNotesReconcileBody": {"type": "object", "required": ["subjectTable", "subjectId", "notes"], "properties": {"subjectTable": {"type": "string", "minLength": 1, "maxLength": 120}, "subjectId": {"type": "string", "minLength": 1, "maxLength": 36}, "notes": {"type": "array", "description": "The complete set for this subject. Anything absent is deleted.", "items": {"$ref": "#/components/schemas/AdminNoteInput"}}}},
  "AdminNoteInput": {"type": "object", "required": ["content"], "properties": {"id": {"type": "string", "maxLength": 36, "description": "Omit to create; supply to update in place"}, "content": {"type": "string", "minLength": 1}}},
  "EntityHistoryEntry": {"type": "object", "description": "One thing that happened to a row. Append-only; nothing here is editable.", "required": ["id", "ecosystemId", "subjectTable", "subjectId", "actorId", "actorLabel", "action", "detail", "createdAt"], "properties": {"id": {"type": "string", "maxLength": 36}, "ecosystemId": {"type": "string", "maxLength": 36}, "subjectTable": {"type": "string", "maxLength": 120}, "subjectId": {"type": "string", "maxLength": 36}, "actorId": {"type": "string", "maxLength": 36, "nullable": true}, "actorLabel": {"type": "string", "maxLength": 120, "nullable": true}, "action": {"type": "string", "maxLength": 60, "description": "Free text, not an enum — each subsystem names its own. Emitted today: request_received, invite_sent, note_added, status_changed, accepted, notes_updated."}, "detail": {"type": "object", "additionalProperties": true, "nullable": true, "description": "Action-specific payload; the shape is whatever emitted the entry."}, "createdAt": {"type": "string"}}},
  "TeamMember": {"type": "object", "required": ["id", "teamId", "memberKind", "userId", "role", "addedAt"], "properties": {"id": {"type": "string"}, "teamId": {"type": "string"}, "memberKind": {"type": "string", "enum": ["customer", "persona"], "description": "which principal userId names — 'customer' (customer.customers) or 'persona' (persona.personas). Present on every response: GET list rows, the add-persona 201, and the by-email add 201 (always a customer)."}, "userId": {"type": "string", "description": "the member principal id — a customer id, or a persona id when memberKind is 'persona'"}, "role": {"type": "string"}, "addedAt": {"type": "string"}, "email": {"type": "string", "nullable": true, "description": "the member's email (resolved; null for a persona member or a foreign customer)"}, "displayName": {"type": "string", "nullable": true}, "personaSlug": {"type": "string", "nullable": true, "description": "the persona's slug when memberKind is 'persona' (null for a customer member)"}, "personaName": {"type": "string", "nullable": true}}},
