  "AccessFeature": {"type": "object", "required": ["key", "label"], "properties": {"key": {"type": "string", "description": "the feature-area key grants are recorded against, e.g. 'audiences'"}, "label": {"type": "string", "description": "the display name for this area (the roles editor labels its row with it)"}}},
  "AccessFeatureList": {"type": "object", "required": ["features"], "properties": {"features": {"type": "array", "items": {"$ref": "#/components/schemas/AccessFeature"}}}},
  "AccessGrant": {"type": "object", "required": ["feature", "itemVerbs", "subitemVerbs"], "properties": {"feature": {"type": "string", "description": "a feature-area key, e.g. 'projects' | 'personas'"}, "itemVerbs": {"type": "string", "description": "top-level item verbs, comma-letter subset of 'C,R,U,D,M' (M = manage access)"}, "subitemVerbs": {"type": "string", "description": "sub-item verbs, subset of 'C,R,U,D'"}}},
  "AccessRole": {"type": "object", "required": ["id", "slug", "name", "description", "isSystem", "defaultFor", "grants"], "properties": {"id": {"type": "string"}, "slug": {"type": "string"}, "name": {"type": "string"}, "description": {"type": "string"}, "isSystem": {"type": "boolean"}, "defaultFor": {"type": "string", "enum": ["", "customer", "persona"], "description": "which member kind holds this role implicitly as the workspace default"}, "grants": {"type": "array", "items": {"$ref": "#/components/schemas/AccessGrant"}}}},
