  "AccessAssignment": {"type": "object", "required": ["id", "subjectKind", "subjectId", "scopeFeature", "scopeItemId", "roleId"], "properties": {"id": {"type": "string"}, "subjectKind": {"type": "string", "enum": ["customer", "persona", "team"]}, "subjectId": {"type": "string"}, "scopeFeature": {"type": "string", "description": "'' = workspace-wide"}, "scopeItemId": {"type": "string", "description": "'' = workspace-wide"}, "roleId": {"type": "string"}, "roleSlug": {"type": "string"}, "roleName": {"type": "string"}, "grantedBy": {"type": "string", "nullable": true}, "grantedAt": {"type": "string"}}},
  "AccessAssignmentList": {"type": "object", "required": ["assignments"], "properties": {"assignments": {"type": "array", "items": {"$ref": "#/components/schemas/AccessAssignment"}}, "restricted": {"type": "boolean", "description": "present on item-scoped listings: whether the item is RESTRICTED"}}},
  "AccessAssignmentEnvelope": {"type": "object", "required": ["assignment"], "properties": {"assignment": {"$ref": "#/components/schemas/AccessAssignment"}}},
