  "TeamReachGrant": {"type": "object", "required": ["id", "ecosystemId", "teamId", "permission", "grantedAt"], "properties": {"id": {"type": "string"}, "ecosystemId": {"type": "string", "description": "the canonical uuid of the ecosystem reached INTO (never the rdid form)"}, "teamId": {"type": "string"}, "permission": {"type": "string", "description": "free-form permission key (max 100 chars)"}, "grantedBy": {"type": "string", "nullable": true, "description": "the user who granted it; null for rows seeded outside this route"}, "grantedAt": {"type": "string"}, "teamName": {"type": "string", "nullable": true}, "teamSlug": {"type": "string", "nullable": true}}},
