  "StorageAttachment": {"type": "object", "required": ["id", "ecosystemId", "customerId", "ownerType", "objectKey", "storageKind", "filename", "contentType", "sizeBytes", "contentHash", "status", "createdAt", "updatedAt"], "properties": {"id": {"type": "string"}, "ecosystemId": {"type": "string"}, "customerId": {"type": "string"}, "ownerType": {"type": "string", "description": "e.g. 'standalone', 'chat_message', 'document'"}, "ownerId": {"type": "string", "nullable": true, "description": "Polymorphic domain owner (NOT the tenant)."}, "objectKey": {"type": "string", "description": "R2 object key the presigned URLs address."}, "storageKind": {"type": "string", "description": "Backing store, e.g. 'r2'."}, "filename": {"type": "string"}, "contentType": {"type": "string"}, "sizeBytes": {"type": "integer"}, "contentHash": {"type": "string"}, "width": {"type": "integer", "nullable": true}, "height": {"type": "integer", "nullable": true}, "durationMs": {"type": "integer", "nullable": true}, "status": {"type": "string", "enum": ["pending", "ready"], "description": "'pending' (presigned, awaiting upload) → 'ready' (bytes confirmed)."}, "metadata": {"type": "object", "additionalProperties": true, "nullable": true, "description": "Caller-supplied JSON metadata (jsonb) — intentionally open."}, "createdAt": {"type": "string"}, "updatedAt": {"type": "string"}, "deletedAt": {"type": "string", "nullable": true}}},
  "StoragePresignedUpload": {"type": "object", "required": ["attachment", "uploadUrl"], "properties": {"attachment": {"$ref": "#/components/schemas/StorageAttachment"}, "uploadUrl": {"type": "string", "format": "uri", "description": "Presigned PUT URL — upload the bytes directly to R2."}}},
