  "StorageAttachmentEnvelope": {"type": "object", "required": ["attachment"], "properties": {"attachment": {"$ref": "#/components/schemas/StorageAttachment"}}},
  "StorageDownload": {"type": "object", "required": ["url"], "properties": {"url": {"type": "string", "format": "uri", "description": "Presigned GET URL — download the bytes directly from R2."}}},
  "SyncManifestEntry": {"type": "object", "required": ["resource", "schemaVersion"], "properties": {"resource": {"type": "string"}, "schemaVersion": {"type": "integer"}}},
  "SyncChange": {"type": "object", "required": ["resource", "id", "op", "syncVersion"], "properties": {"resource": {"type": "string"}, "id": {"type": "string"}, "op": {"type": "string", "enum": ["upsert", "delete"]}, "syncVersion": {"type": "string", "description": "Server-assigned monotonic version (bigint as string)"}, "data": {"type": "object", "additionalProperties": true, "description": "Full row for upserts; absent for deletes"}}},
  "SyncPullResponse": {"type": "object", "required": ["manifest", "changes", "cursor", "hasMore"], "properties": {"manifest": {"type": "array", "items": {"$ref": "#/components/schemas/SyncManifestEntry"}}, "changes": {"type": "array", "items": {"$ref": "#/components/schemas/SyncChange"}}, "cursor": {"type": "string", "description": "Opaque; echo back on the next pull"}, "hasMore": {"type": "boolean"}}},
  "SyncPushOp": {"type": "object", "required": ["opId", "resource", "rowId", "type"], "properties": {"opId": {"type": "string", "format": "uuid", "description": "Client-generated UUIDv7 idempotency key"}, "resource": {"type": "string"}, "rowId": {"type": "string", "format": "uuid", "description": "Client-generated row id (offline creation)"}, "type": {"type": "string", "enum": ["upsert", "delete"]}, "baseVersion": {"type": "string", "description": "sync_version the client last saw; stale → conflict"}, "data": {"type": "object", "additionalProperties": true}}},
  "SyncPushRequest": {"type": "object", "required": ["deviceId", "ops"], "properties": {"deviceId": {"type": "string"}, "ops": {"type": "array", "items": {"$ref": "#/components/schemas/SyncPushOp"}, "minItems": 1, "maxItems": 500}}},
  "SyncPushResult": {"type": "object", "required": ["opId", "status"], "properties": {"opId": {"type": "string", "format": "uuid"}, "status": {"type": "string", "enum": ["applied", "conflict", "rejected"]}, "reason": {"type": "string"}, "current": {"type": "object", "additionalProperties": true, "nullable": true}, "newVersion": {"type": "string", "description": "Post-apply sync_version; present only on `applied` results that wrote a row (absent for an idempotent no-op delete). Clients SHOULD adopt it as the row's new baseVersion for subsequent staged edits."}}},
  "SyncPushResponse": {"type": "object", "required": ["results", "watermark"], "properties": {"results": {"type": "array", "items": {"$ref": "#/components/schemas/SyncPushResult"}}, "watermark": {"type": "string"}}},
  "SyncEnrollmentRow": {"type": "object", "description": "One resource from the sync catalog as it stands for a given ecosystem: what the code ships as the default, and whether an operator has overridden it.", "required": ["resource", "scope", "pushMode", "defaultEnabled", "enabled", "overridden"], "properties": {"resource": {"type": "string", "description": "\"<schema>.<table>\", e.g. content.contacts"}, "scope": {"type": "string", "enum": ["customer", "ecosystem"]}, "pushMode": {"type": "string", "enum": ["generic", "route"], "description": "'route' means /sync/push refuses direct writes; the row's own route owns them"}, "defaultEnabled": {"type": "boolean", "description": "What the shipped catalog says"}, "enabled": {"type": "boolean", "description": "What is actually in force — the override if there is one"}, "overridden": {"type": "boolean"}}},
  "SyncEnrollmentList": {"type": "object", "required": ["tables"], "properties": {"tables": {"type": "array", "items": {"$ref": "#/components/schemas/SyncEnrollmentRow"}}}},
  "SyncEnrollmentUpdate": {"type": "object", "required": ["enabled"], "properties": {"enabled": {"type": "boolean"}}},
