  "PATCH /organization/organizations/{id}": {"key": "PATCH /organization/organizations/{id}", "method": "PATCH", "path": "/organization/organizations/{id}", "tag": "registry", "summary": "Update an organization (name/description: org-team admin or site-admin; slug: site-admin only — re-mints the global rdids)", "params": [{"name": "id", "in": "path", "required": true, "schema": {"type": "string"}}], "description": "Update fields of a record in organizations by id.", "requestBody": {"required": false, "contentType": "application/json", "schema": {"type": "object", "description": "At least one of name, slug, or description is required.", "minProperties": 1, "properties": {"name": {"type": "string", "minLength": 1, "maxLength": 255}, "slug": {"type": "string", "pattern": "^[a-z0-9][a-z0-9_-]{1,63}$"}, "description": {"type": "string", "maxLength": 1000}}}}, "responses": [{"status": "200", "description": "organization", "contentType": "application/json", "schema": {"$ref": "#/components/schemas/RegistryOrganization"}}, {"status": "400", "description": "Error", "contentType": "application/json", "schema": {"$ref": "#/components/schemas/Error"}}, {"status": "401", "description": "Error", "contentType": "application/json", "schema": {"$ref": "#/components/schemas/Error"}}, {"status": "403", "description": "Error", "contentType": "application/json", "schema": {"$ref": "#/components/schemas/Error"}}, {"status": "404", "description": "Error", "contentType": "application/json", "schema": {"$ref": "#/components/schemas/Error"}}, {"status": "409", "description": "Error", "contentType": "application/json", "schema": {"$ref": "#/components/schemas/Error"}}], "security": ["bearerAuth"], "family": ["DELETE /organization/organizations/{id}", "GET /organization/organizations", "GET /organization/organizations/{key}", "PATCH /organization/organizations/{id}", "POST /organization/organizations", "POST /organization/organizations/{id}/restore"]},
  "PATCH /persona/mcp-servers/{id}": {"key": "PATCH /persona/mcp-servers/{id}", "method": "PATCH", "path": "/persona/mcp-servers/{id}", "tag": "registry", "summary": "Update / enable / disable / rotate the secret of an MCP server (site-admin)", "params": [{"name": "id", "in": "path", "required": true, "schema": {"type": "string"}}], "description": "Update fields of a record in mcp-servers by id.", "requestBody": {"required": false, "contentType": "application/json", "schema": {"type": "object", "description": "All fields optional. A blank or absent authSecret PRESERVES the stored secret; a present non-empty value rotates it.", "properties": {"name": {"type": "string", "minLength": 1, "maxLength": 255}, "url": {"type": "string", "minLength": 1, "maxLength": 500}, "enabled": {"type": "boolean"}, "authSecret": {"type": "string", "description": "Blank/absent preserves the stored secret; a non-empty value rotates it"}}}}, "responses": [{"status": "200", "description": "the updated server (secret redacted)", "contentType": "application/json", "schema": {"type": "object", "required": ["server"], "properties": {"server": {"$ref": "#/components/schemas/RegistryAgentMcpServer"}}}}, {"status": "400", "description": "Error", "contentType": "application/json", "schema": {"$ref": "#/components/schemas/Error"}}, {"status": "401", "description": "Error", "contentType": "application/json", "schema": {"$ref": "#/components/schemas/Error"}}, {"status": "403", "description": "Error", "contentType": "application/json", "schema": {"$ref": "#/components/schemas/Error"}}, {"status": "404", "description": "Error", "contentType": "application/json", "schema": {"$ref": "#/components/schemas/Error"}}], "security": ["bearerAuth"], "family": ["DELETE /persona/mcp-servers/{id}", "GET /persona/mcp-servers", "GET /persona/mcp-servers/{id}", "PATCH /persona/mcp-servers/{id}", "POST /persona/mcp-servers"]},
