  "POST /content/markdown/{id}/unpublish": {"key": "POST /content/markdown/{id}/unpublish", "method": "POST", "path": "/content/markdown/{id}/unpublish", "tag": "content", "summary": "Unpublish a document (revert to a private draft, freeing its route)", "params": [{"name": "id", "in": "path", "required": true, "schema": {"type": "string"}}, {"name": "workspace", "in": "query", "required": false, "schema": {"type": "string"}, "description": "Scope to this WORKSPACE’s owning principal (the caller’s own customer slug, or an organization the caller belongs to). Omitted: the caller’s own documents. Unknown/foreign slug: 404."}], "responses": [{"status": "200", "description": "The unpublished document", "contentType": "application/json", "schema": {"$ref": "#/components/schemas/MarkdownDocument"}}, {"status": "401", "description": "Error", "contentType": "application/json", "schema": {"$ref": "#/components/schemas/Error"}}, {"status": "404", "description": "Error", "contentType": "application/json", "schema": {"$ref": "#/components/schemas/Error"}}], "security": ["bearerAuth"], "family": ["DELETE /content/markdown/{id}", "GET /content/markdown", "GET /content/markdown/categories", "GET /content/markdown/export", "GET /content/markdown/tags", "GET /content/markdown/{id}", "GET /content/markdown/{id}/raw", "POST /content/markdown", "POST /content/markdown/categories", "POST /content/markdown/{id}/definalize", "POST /content/markdown/{id}/finalize", "POST /content/markdown/{id}/publish", "POST /content/markdown/{id}/unpublish", "PUT /content/markdown/{id}"]},
