  "POST /customer/login": {"key": "POST /customer/login", "method": "POST", "path": "/customer/login", "tag": "customer", "summary": "Authenticate one of the caller's end-customers (email + password)", "params": [], "description": "Create a record in login.", "requestBody": {"required": false, "contentType": "application/json", "schema": {"type": "object", "description": "email or identifier is required (identifier is the generic alias).", "required": ["password"], "properties": {"email": {"type": "string"}, "identifier": {"type": "string"}, "password": {"type": "string"}}}}, "responses": [{"status": "200", "description": "customer access token + opaque refresh token + customerId", "contentType": "application/json", "schema": {"$ref": "#/components/schemas/CustomerAuthResult"}}, {"status": "202", "description": "second factor required", "contentType": "application/json", "schema": {"$ref": "#/components/schemas/MfaChallenge"}}, {"status": "400", "description": "Error", "contentType": "application/json", "schema": {"$ref": "#/components/schemas/Error"}}, {"status": "401", "description": "Error", "contentType": "application/json", "schema": {"$ref": "#/components/schemas/Error"}}], "security": ["bearerAuth"], "family": ["POST /customer/login", "POST /customer/login/mfa"]},
  "POST /customer/login/mfa": {"key": "POST /customer/login/mfa", "method": "POST", "path": "/customer/login/mfa", "tag": "customer", "summary": "Complete customer login by satisfying the second factor → aal=2 session", "params": [], "requestBody": {"required": false, "contentType": "application/json", "schema": {"type": "object", "required": ["token", "method", "code"], "properties": {"token": {"type": "string", "description": "MFA pending token"}, "method": {"type": "string", "enum": ["sms", "totp", "recovery"]}, "code": {"type": "string", "maxLength": 40}}}}, "responses": [{"status": "200", "description": "customer access token + opaque refresh token + customerId", "contentType": "application/json", "schema": {"$ref": "#/components/schemas/CustomerAuthResult"}}, {"status": "400", "description": "Error", "contentType": "application/json", "schema": {"$ref": "#/components/schemas/Error"}}, {"status": "401", "description": "Error", "contentType": "application/json", "schema": {"$ref": "#/components/schemas/Error"}}, {"status": "409", "description": "Error", "contentType": "application/json", "schema": {"$ref": "#/components/schemas/Error"}}], "security": ["bearerAuth"], "family": ["POST /customer/login", "POST /customer/login/mfa"]},
