  "PUT /me/communication-settings": {"key": "PUT /me/communication-settings", "method": "PUT", "path": "/me/communication-settings", "tag": "settings", "summary": "Replace the caller's communication/presence dial (upsert; full representation)", "params": [], "description": "Masks must combine only the known AUDIENCE bits (PUBLIC=1, HUB=2, TEAM=4, ORG=8, FRIEND=32); 0 means nobody. Blocks always override the dial, and appear_offline hides presence from everyone.", "requestBody": {"required": false, "contentType": "application/json", "schema": {"type": "object", "required": ["dmAudienceMask", "presenceAudienceMask", "appearOffline"], "properties": {"dmAudienceMask": {"type": "integer", "minimum": 0, "description": "AUDIENCE bitmask of who may DM the user (0 = nobody; default PUBLIC|HUB = 3)"}, "presenceAudienceMask": {"type": "integer", "minimum": 0, "description": "AUDIENCE bitmask of who may see the user presence (0 = nobody; default PUBLIC|HUB = 3)"}, "appearOffline": {"type": "boolean", "description": "When true, presence is hidden from EVERYONE regardless of the mask"}}}}, "responses": [{"status": "200", "description": "The saved communication dial", "contentType": "application/json", "schema": {"$ref": "#/components/schemas/CommunicationSettings"}}, {"status": "400", "description": "Error", "contentType": "application/json", "schema": {"$ref": "#/components/schemas/Error"}}, {"status": "401", "description": "Error", "contentType": "application/json", "schema": {"$ref": "#/components/schemas/Error"}}], "security": ["bearerAuth"], "family": ["GET /me/communication-settings", "PUT /me/communication-settings"]},
