  "PUT /shipr/repos/{id}/platforms/{kind}": {"key": "PUT /shipr/repos/{id}/platforms/{kind}", "method": "PUT", "path": "/shipr/repos/{id}/platforms/{kind}", "tag": "shipr", "summary": "Attach a stored platform credential to this repository", "params": [{"name": "id", "in": "path", "required": true, "schema": {"type": "string"}, "description": "A deploy repository (mirror) id."}, {"name": "kind", "in": "path", "required": true, "schema": {"type": "string"}, "description": "The platform. Only `vercel` today: Railway builds from the push it watches and exposes nothing a token could ask, so a row for it would be data nothing reads and this route refuses to write one."}], "description": "WITHOUT THIS THE DEPLOY PIPELINE CANNOT CHECK ARRIVALS. The Vercel adapter is built from this row and from nowhere else; with no row the platform resolves to 'the push is the deployment', and a deploy whose build never ran passes. The connection must be the CALLER's own and its provider must equal `kind` — a credential for another provider would be handed to this platform's API on the next deploy. Idempotent: re-attaching replaces the id in place.", "requestBody": {"required": false, "contentType": "application/json", "schema": {"type": "object", "required": ["connectionId"], "properties": {"connectionId": {"type": "string"}}}}, "responses": [{"status": "200", "description": "The credential was re-pointed", "contentType": "application/json", "schema": {"type": "object", "required": ["kind", "connectionId"], "properties": {"kind": {"type": "string"}, "connectionId": {"type": "string"}}}}, {"status": "201", "description": "The credential was attached", "contentType": "application/json", "schema": {"type": "object", "required": ["kind", "connectionId"], "properties": {"kind": {"type": "string"}, "connectionId": {"type": "string"}}}}, {"status": "400", "description": "Error", "contentType": "application/json", "schema": {"$ref": "#/components/schemas/Error"}}, {"status": "401", "description": "Error", "contentType": "application/json", "schema": {"$ref": "#/components/schemas/Error"}}, {"status": "403", "description": "Error", "contentType": "application/json", "schema": {"$ref": "#/components/schemas/Error"}}, {"status": "404", "description": "Error", "contentType": "application/json", "schema": {"$ref": "#/components/schemas/Error"}}], "security": ["bearerAuth"], "family": ["DELETE /shipr/repos/{id}/platforms/{kind}", "GET /shipr/repos/{id}/platforms", "PUT /shipr/repos/{id}/platforms/{kind}"]},
  "PUT /system/admin-notes": {"key": "PUT /system/admin-notes", "method": "PUT", "path": "/system/admin-notes", "tag": "system", "summary": "Reconcile a subject's admin notes", "params": [], "description": "Replaces the whole set for the subject rather than editing one note: a note with an `id` is updated, one without is created, and any existing note the body omits is DELETED. Sending an empty `notes` array clears them all. Appends one `notes_updated` entry to the subject's history.", "requestBody": {"required": false, "contentType": "application/json", "schema": {"$ref": "#/components/schemas/AdminNotesReconcileBody"}}, "responses": [{"status": "200", "description": "Success", "contentType": "application/json", "schema": {"type": "object", "required": ["ok"], "properties": {"ok": {"type": "boolean"}}}}, {"status": "400", "description": "Error", "contentType": "application/json", "schema": {"$ref": "#/components/schemas/Error"}}, {"status": "401", "description": "Error", "contentType": "application/json", "schema": {"$ref": "#/components/schemas/Error"}}, {"status": "403", "description": "Error", "contentType": "application/json", "schema": {"$ref": "#/components/schemas/Error"}}], "security": ["bearerAuth"], "family": ["GET /system/admin-notes", "PUT /system/admin-notes"]},
